static bool run_case(const std::string& name, int n, bool visible) {
    std::mt19937 rng(n);
    std::uniform_real_distribution<float> dist(-100.f, 100.f);
    std::vector<float> a(n), b(n), c(n, -1.f);
    for (int i = 0; i < n; ++i) { a[i] = dist(rng); b[i] = dist(rng); }
    float *da, *db, *dc;
    size_t bytes = sizeof(float) * n;
    cudaMalloc(&da, bytes); cudaMalloc(&db, bytes); cudaMalloc(&dc, bytes);
    cudaMemcpy(da, a.data(), bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(db, b.data(), bytes, cudaMemcpyHostToDevice);
    cudaMemset(dc, 0xff, bytes);  // NaN pattern: untouched elements fail
    launch_vector_add(da, db, dc, n);
    cudaError_t err = cudaDeviceSynchronize();
    if (err == cudaSuccess) err = cudaGetLastError();
    cudaMemcpy(c.data(), dc, bytes, cudaMemcpyDeviceToHost);
    cudaFree(da); cudaFree(db); cudaFree(dc);
    if (err != cudaSuccess) {
        lc::error(name, std::string("CUDA error: ") + cudaGetErrorString(err), visible);
        return false;
    }
    for (int i = 0; i < n; ++i) {
        float want = a[i] + b[i];
        if (!(std::fabs(c[i] - want) <= 1e-5f * std::fabs(want) + 1e-6f)) {
            char msg[160];
            std::snprintf(msg, sizeof msg, "c[%d] = %g, expected %g", i, c[i], want);
            lc::test(name, false, "every element equals a[i] + b[i]", msg, "", visible);
            return false;
        }
    }
    lc::test(name, true, "every element equals a[i] + b[i]", "all match", "", visible);
    return true;
}

int main() {
    run_case("n = 1", 1, true);
    run_case("n = 1000", 1000, true);
    run_case("n = 256 (exactly one block)", 256, false);
    run_case("n = 12345 (partial last block)", 12345, false);
    run_case("n = 2^22", 1 << 22, false);
    return 0;
}

